-- =============================================================
-- SLIS demo data -- Tier 2
-- Database: SLIS THESIS FINAL (PostgreSQL)
-- Run with: psql -U postgres -d "SLIS THESIS FINAL" -f seed_data.sql
--
-- 31 learners with complete profiles across two connected school years:
--   S.Y. 2025-2026: 25 learners, finished (completed, plus a transfer-out, a
--               dropout and a cancellation).
--   S.Y. 2026-2027: 25 learners, the current year, filled up to 2026-09-30
--               (Q1 graded, Q2 in progress; enrolled, pending, cancelled,
--               transferred out).
-- 19 learners continue from one year to the next (promotions, two
-- retentions, two overrides). Plus online-intake applications and invites.
--
-- Accounts (password SlisDemo2026! for all that can sign in):
--   superadmin@slis.test  super_admin   admin@slis.test         admin
--   registrar@slis.test   registrar     jocelyn.ramos@slis.test registrar
--   accounting@slis.test  accounting    arvin.lacson@slis.test  accounting
--   ramon.estrada@slis.test registrar (a 2025-26 adviser, now registrar)
--   teacher@slis.test     teacher (adviser of Grade 5 Silang)
--   arnel.pascual@slis.test, maricar.santiago@slis.test: INACTIVE (resigned)
--   maribel.reyes.seed@gmail.com, maria.dizon.seed@gmail.com,
--   perla.ibarra.seed@gmail.com, danilo.jimenez.seed@gmail.com: guardians
--
-- Re-runnable: this seed's learners (LRN block 136700000...) and its
-- intake rows are cleared and rebuilt; shared set-up is only added where
-- missing; staff accounts are reset.
-- Generated by a script -- edit the generator, not this file, for changes.
-- =============================================================

BEGIN;


-- =====================================================
-- 0. CLEAR THIS SEED'S OWN ROWS
-- Everything downstream of a learner in the seed's LRN block goes first, child
-- tables before parents. Invoices, attendance and transfers do not cascade
-- from an enrollment (RESTRICT / NO ACTION, correctly), so they are removed
-- explicitly. The seed's own applications and invites (fixed ids) go too;
-- applications first, because the database does not cascade that FK.
-- Rows for any other learner are never touched. Shared set-up (years,
-- subjects, sections, calendar, fees, accounts) is insert-if-missing below.
-- =====================================================

CREATE TEMP TABLE seed_learner_ids ON COMMIT DROP AS
  SELECT student_id FROM students WHERE lrn LIKE '136700000%';
CREATE TEMP TABLE seed_enrollment_ids ON COMMIT DROP AS
  SELECT enrollment_id FROM enrollments WHERE student_id IN (SELECT student_id FROM seed_learner_ids);

DELETE FROM student_applications WHERE student_application_id IN (700, 701, 702, 703, 704, 705, 706, 707, 708, 709, 710, 711, 712);
DELETE FROM application_invites  WHERE invite_id IN ('63aa64a8-6b3c-5850-a5a0-48e4c78db08b'::uuid, '1f7f9b89-25dd-5abe-9c75-507ca003cabf'::uuid, '54003a74-5d55-5ea3-b0c9-9161db5ed097'::uuid, '5089f390-6924-5daa-bd62-de2b64b2f6b1'::uuid, 'b7aeb11b-fe63-5517-8249-f2054d8aba98'::uuid, '0f7798a2-7b72-5822-abb1-14c5b2d5785f'::uuid, 'a714aaf5-9d28-579f-9089-f628e5a10c85'::uuid, '8b69a88f-0849-55e4-b020-8325e178fa36'::uuid, '51c712cc-ad61-507c-8cf3-e3a0da1206fa'::uuid, 'd63b829e-413b-521b-af90-0c7cabcb5a9e'::uuid, '9134432f-7459-5269-8a1b-0134298586f9'::uuid, 'f48a4380-80af-5735-9bec-fb61016e7f1a'::uuid, '44859680-05fe-533e-aecf-7d037c154987'::uuid, '2659ea29-1106-5011-a137-90e970bb7780'::uuid, '724d7aa0-de0d-59ca-b0c4-0d669181a6ef'::uuid, '4131610b-fb19-533e-abc1-a25638f50465'::uuid, '9b9c6010-d38d-5bfe-899d-385201444147'::uuid, 'f4226863-ac3d-528d-9ea2-8e172ef90c01'::uuid, '59b7fde3-b0c7-50cc-9466-e26b6e938821'::uuid);
DELETE FROM student_invoices     WHERE enrollment_id IN (SELECT enrollment_id FROM seed_enrollment_ids);
DELETE FROM attendance_records   WHERE enrollment_id IN (SELECT enrollment_id FROM seed_enrollment_ids);
DELETE FROM enrollment_transfers WHERE enrollment_id IN (SELECT enrollment_id FROM seed_enrollment_ids);
DELETE FROM student_risk_scores  WHERE student_id    IN (SELECT student_id FROM seed_learner_ids);
DELETE FROM document_extractions WHERE student_id    IN (SELECT student_id FROM seed_learner_ids);
DELETE FROM enrollments          WHERE enrollment_id IN (SELECT enrollment_id FROM seed_enrollment_ids);
DELETE FROM students             WHERE student_id    IN (SELECT student_id FROM seed_learner_ids);
DELETE FROM households h
 WHERE h.household_id IN (100, 104, 105, 110, 111, 112, 113, 114, 115, 116, 117, 120, 125, 126, 127, 128, 129, 131, 138, 140, 141, 143, 147, 148, 151, 155, 156, 157, 159, 160, 161, 162, 163, 164, 165, 166, 167, 168, 169, 170, 171, 172, 173, 174, 175, 176, 177, 178, 179, 180, 181, 182, 183, 184, 185, 186, 187, 188, 189, 190, 191, 192, 193, 194, 195, 196, 197, 198, 199, 200, 201, 202, 203, 204, 205, 206, 207, 208, 209, 210, 211, 212, 213, 214, 215, 216, 217, 218, 219, 220, 221, 222, 223, 224, 225, 226, 227, 228, 229, 230, 231, 232, 233, 234, 235, 236, 237, 238, 239, 240, 241, 242, 243, 244, 245, 246, 247, 248, 249, 250, 251, 252, 253, 254, 255, 256, 257, 258, 259, 260, 261, 262, 263, 264, 265, 266, 267, 268, 269, 270, 271, 272, 273, 274, 275, 276, 277, 278, 279, 280, 281, 282, 283, 284, 285, 286, 287, 288, 289, 290, 291, 292, 293, 294, 295, 296, 297, 298, 299, 300, 301, 302, 303, 304, 305, 306, 307, 308, 309, 310, 311, 312, 313, 314, 315, 316, 317, 318, 319, 320, 321, 322, 323, 324, 325, 326, 327, 328, 329, 330, 331, 332, 333, 334, 335, 336, 337, 338, 339, 340, 341, 342, 343, 344, 345, 346, 347, 348, 349, 350, 351, 352, 353, 354, 355, 356, 357, 358, 359, 360, 361, 362, 363, 364, 365, 366, 367, 368, 369, 370, 371, 372, 373, 374, 375, 376)
   AND NOT EXISTS (SELECT 1 FROM students s WHERE s.household_id = h.household_id);


-- =====================================================
-- 1. REFERENCE DATA
-- Requirement catalogue, DepEd grading templates and the four core values.
-- Must come before subjects, scores and observed values, which use them.
-- =====================================================

\ir scripts/reference_data.sql


-- =====================================================
-- 2. SCHOOL YEARS
-- 2025-2026 is finished (every attended enrollment completed). 2026-2027 is the
-- current year, filled up to the day the file was generated. It becomes the
-- current year only when no year is current yet.
-- =====================================================

VALUES ('2025-2026', '2025-06-01', '2026-03-31', FALSE, now(), now())
ON CONFLICT (label) DO NOTHING;

SELECT '2026-2027', '2026-06-01', '2027-03-31',
       NOT EXISTS (SELECT 1 FROM school_years WHERE is_current), now(), now()
ON CONFLICT (label) DO NOTHING;

-- School Settings mirrors the registry's current year (the API keeps these
-- read-only for that reason); the letterhead fields are the demo school's.
UPDATE school_settings s
   SET current_school_year = y.label,
       sy_start_date       = y.start_date,
       sy_end_date         = y.end_date,
       early_bird_days     = 7,
       school_name         = 'South Lakes Integrated School',
       school_address      = '12 Lakeview Road, Brgy. San Isidro, Marikina City, Metro Manila 1800',
       contact_email       = 'registrar@slis.test',
       contact_phone       = '(02) 8123-4567',
       updated_at          = now()
  FROM school_years y
 WHERE y.is_current;


